abstract final class Radii {
  static const double chip = 999.0;
  static const double pill = 16.0;
  static const double card = 14.0;
  static const double button = 12.0;
  static const double key = 10.0;
  static const double small = 8.0;
  static const double dialog = 18.0;
}

abstract final class Sizes {
  static const double touchTarget = 44.0;
  static const double toolbarHeight = 52.0;
  static const Size tabletFrame = Size(1280.0, 800.0);
  static const double paperDotSpacing = 26.0;
  static const double paperDotRadius = 1.3;
}

abstract final class FontFamilies {
  static const ui = 'Figtree';
  static const serif = 'Newsreader';
  static const handwritingSample = 'Caveat';
}

/// Type scale. Text case (e.g. uppercase section labels) is applied by the widget.
abstract final class TypeScale {
  static const pillTitle = TextStyle(fontFamily: 'Figtree', fontSize: 16.0, fontWeight: FontWeight.w600);
  static const pillSub = TextStyle(fontFamily: 'Figtree', fontSize: 13.0, fontWeight: FontWeight.w400);
  static const button = TextStyle(fontFamily: 'Figtree', fontSize: 14.0, fontWeight: FontWeight.w600);
  static const sectionLabel = TextStyle(fontFamily: 'Figtree', fontSize: 12.0, fontWeight: FontWeight.w600, letterSpacing: 0.96);
  static const panelTitle = TextStyle(fontFamily: 'Newsreader', fontSize: 24.0, fontWeight: FontWeight.w400);
  static const pageHeading = TextStyle(fontFamily: 'Newsreader', fontSize: 34.0, fontWeight: FontWeight.w400);
}
